// ---------- state ----------
let lang='en';
let st=blank();
let photos={};
let step=0;
let resMode='found', demoMode='found', demoTimer=null, glossSel='parked';
let palMore=false, locBusy=false, locFail=false;
const DEMO={gate:'no',i1:'yes',i2:'partly',i3:'no',i4:'no',i5:'yes',i6:'no',i7:'partly',i8:'no',i9:'no',i10:'yes'};
const DEMO_OBS=['parked','electric','vendor','manhole','parked'];
function blank(){return {mode:null,locate:{road:'',area:'',from:'',to:'',side:'',divider:null,lanes:null,through:null,gates:null,land:'homes',count:''},loc:{start:null,end:null},quick:{gate:null},answers:{},obs:[],auto:{},meta:{date:new Date().toISOString()},owner:'unknown',name:'',org:'',hhrc:true}}
function normalise(s){s.mode=s.mode||(Object.keys(s.answers||{}).length?'full':null);s.loc=s.loc||{start:null,end:null};s.quick=s.quick||{gate:null};s.obs=migrateObs(s.obs);s.auto=s.auto||{};if(s.locate&&s.locate.side&&!['left','right'].includes(s.locate.side)){s.locate.road=[s.locate.road,s.locate.from&&s.locate.to?`${s.locate.from} to ${s.locate.to}`:'',s.locate.side].filter(Boolean).join(', ');s.locate.side=''}return s}
const T=k=>S[lang][k];
const $=id=>document.getElementById(id);
function ls(fn){try{return fn()}catch(e){return null}}
function saveDraft(){ls(()=>localStorage.setItem('fc_draft',JSON.stringify(st)))}
function loadDraft(){return ls(()=>JSON.parse(localStorage.getItem('fc_draft')||'null'))}
function toast(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');clearTimeout(t._h);t._h=setTimeout(()=>t.classList.remove('show'),1800)}
function esc(s){return String(s==null?'':s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}
async function copyText(txt){try{await navigator.clipboard.writeText(txt);toast(T('copied'))}catch(e){const ta=document.createElement('textarea');ta.value=txt;document.body.appendChild(ta);ta.select();try{document.execCommand('copy');toast(T('copied'))}catch(e2){toast('Select and copy by hand')}document.body.removeChild(ta)}}
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function nm(o){return lang==='hi'?o.hi:o.en}
const isQuick=()=>st.mode==='quick';

// ---------- location ----------
function getFix(cb){if(!navigator.geolocation){cb(null,'nogeo');return}
 let done=false;const fin=(a,b)=>{if(done)return;done=true;cb(a,b)};
 try{navigator.geolocation.getCurrentPosition(p=>fin({lat:+p.coords.latitude.toFixed(4),lon:+p.coords.longitude.toFixed(4),acc:Math.round(p.coords.accuracy||0),t:new Date().toISOString()}),e=>fin(null,e&&e.code===1?'denied':'fail'),{enableHighAccuracy:true,timeout:12000,maximumAge:20000})}catch(e){fin(null,'fail')}
 setTimeout(()=>fin(null,'timeout'),14000)}
function distM(a,b){const R=6371000,r=x=>x*Math.PI/180;const dLat=r(b.lat-a.lat),dLon=r(b.lon-a.lon);const s=Math.sin(dLat/2)**2+Math.cos(r(a.lat))*Math.cos(r(b.lat))*Math.sin(dLon/2)**2;return Math.round(2*R*Math.asin(Math.sqrt(s)))}
function bearing(a,b){const r=x=>x*Math.PI/180;const y=Math.sin(r(b.lon-a.lon))*Math.cos(r(b.lat));const x=Math.cos(r(a.lat))*Math.sin(r(b.lat))-Math.sin(r(a.lat))*Math.cos(r(b.lat))*Math.cos(r(b.lon-a.lon));return (Math.atan2(y,x)*180/Math.PI+360)%360}
function compass(deg){return ['N','NE','E','SE','S','SW','W','NW'][Math.round(deg/45)%8]}
function mapUrl(f){return `https://www.openstreetmap.org/?mlat=${f.lat}&mlon=${f.lon}#map=18/${f.lat}/${f.lon}`}
function parseCoords(s){const m=String(s||'').match(/(-?\d{1,2}\.\d{3,})\s*,?\s+(-?\d{1,3}\.\d{3,})/)||String(s||'').match(/(-?\d{1,2}\.\d{3,}),(-?\d{1,3}\.\d{3,})/);if(!m)return null;const lat=+(+m[1]).toFixed(4),lon=+(+m[2]).toFixed(4);if(Math.abs(lat)>90||Math.abs(lon)>180)return null;return {lat,lon,acc:0,t:new Date().toISOString(),manual:true}}
function fixText(f){return f?`${f.lat.toFixed(4)}, ${f.lon.toFixed(4)}`:''}
function stretchLen(){const l=st.loc;if(l.start&&l.end){const d=distM(l.start,l.end);return d>20?d:null}return null}
function placeText(){const l=st.locate;if(l.road)return l.road;if(st.loc.start)return fixText(st.loc.start);return ''}
function sideText(en){const s=st.locate.side;if(!s)return '';const dir=st.loc.start&&st.loc.end?compass(bearing(st.loc.start,st.loc.end)):'';if(en)return `${s}-hand side${dir?' walking '+dir:''}`;return (s==='left'?T('side_left'):T('side_right'))+(dir?` (${dir})`:'')}

// ---------- classification and scoring ----------
function roadClass(l){if(l.divider==null||l.lanes==null||l.through==null||l.gates==null)return null;const lanes=+l.lanes,div=l.divider==='yes',thr=l.through==='yes',gates=l.gates==='yes';if(div&&lanes>=3)return 'arterial';if(div||(lanes>=2&&thr))return 'subarterial';if(lanes>=2||thr)return 'collector';if(gates)return 'local';return 'collector'}
function scoreOf(a){let got=0,max=0,n=0;const fails=[];for(const it of ITEMS){if(!it.w)continue;let v=a[it.id];if(a.i1==='no'&&it.nf)v='no';if(v==null||v==='cant')continue;max+=it.w;n++;if(v==='yes')got+=it.w;else if(v==='partly'){got+=it.w/2;fails.push({it,v})}else fails.push({it,v})}
 const s=max?Math.round(got/max*100):null;const gate=a.gate;let band=null;if(s!=null){band=gate==='no'?'r':(s>=70?'g':(s>=40?'a':'r'))}fails.sort((x,y)=>y.it.w-x.it.w);return {s,band,fails,n,max}}
function complete(a){for(const it of ITEMS){if(it.anchor)continue;let v=a[it.id];if(a.i1==='no'&&it.nf)continue;if(v==null)return false}return true}
const OBS_OLD={car:'parked',bike:'parked',stall:'shop',cart:'vendor',tin:'vendor',pole:'electric',transformer:'electric',tree:'green',overgrown:'green',debris:'waste',garbage:'waste',shelter:'furniture',hoarding:'furniture',drain:'manhole'};
function migrateObs(list){return (list||[]).map(id=>OBS_BY[id]?id:(OBS_OLD[id]||null)).filter(Boolean)}
function obsCounts(list){const c={};for(const id of list||[])c[id]=(c[id]||0)+1;return c}
const SURFACE_OBS=['manhole','slab','dug','water'];
function suggestFromObs(){const list=st.obs||[];const total=list.length;const off=list.filter(id=>{const s=OBS_BY[id]?.sev;return s==='off'||s==='fall'}).length;
 const a=st.answers;st.auto=st.auto||{};
 if(a.i2==null||st.auto.i2){if(total===0){if(st.auto.i2){delete a.i2;delete st.auto.i2}}else{a.i2=(off>=1&&total>=3)||total>=4?'no':(off>=2?'no':'partly');st.auto.i2=true}}
 const surf=list.some(id=>SURFACE_OBS.includes(id));
 if(a.i7==null||st.auto.i7){if(surf){a.i7=list.some(id=>['manhole','slab','dug'].includes(id))?'no':'partly';st.auto.i7=true}else if(st.auto.i7){delete a.i7;delete st.auto.i7}}}
function obsAsks(limit){const c=obsCounts(st.obs);const ids=Object.keys(c).sort((x,y)=>(x==='manhole'?-1:y==='manhole'?1:0));const out=[];for(const id of ids){const o=OBS_BY[id];if(o&&!out.some(p=>p.fix===o.fix))out.push(o)}return out.slice(0,limit||3)}

