 if(!noFp&&v('i9')==='no'){for(const x of [150,430,700]){s+=`<rect x="${x-34}" y="${fpTop}" width="68" height="${150-fpTop}" style="fill:url(#hz${id})"/><path d="M${x-34} ${fpTop} L${x-34} 150 M${x+34} ${fpTop} L${x+34} 150" style="stroke:var(--ink);stroke-width:2;stroke-dasharray:6 4"/><path d="M${x-30} ${fpTop+10} L${x+30} 142" style="stroke:var(--ink);stroke-width:3;opacity:.5"/><rect x="${x-22}" y="24" width="44" height="16" rx="2" style="fill:var(--ink)"/><path d="M${x} 24V40" style="stroke:var(--bg);stroke-width:2"/>`}}
